contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);

        uint testBalBefore = address(this).balance;
        uint cBalBefore = address(c).balance;

        c.play{value: amount}();

        uint testBalAfter = address(this).balance;
        uint cBalAfter = address(c).balance;

        // Conservation: a loss just adds 10 wei to the contract;
        // a win pays out to the caller/bank (this test) exactly what
        // the contract loses. Either way the combined balance grows
        // by exactly the ticket amount.
        assert(cBalAfter + testBalAfter == cBalBefore + testBalBefore + 10);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);
        require(address(c).balance < 2**200);
        require(c.pot() < 2**200);
        require(address(c).balance >= c.pot());

        uint potBefore = c.pot();
        uint cBalBefore = address(c).balance;

        c.play{value: amount}();

        uint potAfter = c.pot();
        uint cBalAfter = address(c).balance;

        // Loss: pot and balance both grew by the ticket amount.
        // Win: pot is fully reset and the whole old pot left the contract.
        assert(
            potAfter == potBefore + 10
                ? cBalAfter == cBalBefore + amount
                : (potAfter == 0 && cBalAfter == cBalBefore - potBefore)
        );
    }

    receive() external payable {}
}

